// Spec tests for bill files on the relay (docs/context/BILLS_API.md §4, RELAY_PROTOCOL.md "Blobs"), written from the spec
// only. All data is SYNTHETIC (generated bytes). `// SPEC:` marks a reading of an ambiguous spec line.
import 'dart:math';
import 'dart:typed_data';

import 'package:cryptography/cryptography.dart';
import 'package:test/test.dart';
import 'package:wallet_core/wallet_core.dart';

Uint8List bytesOf(int n, [int seed = 1]) {
  final r = Random(seed);
  return Uint8List.fromList(List.generate(n, (_) => r.nextInt(256)));
}

Future<String> sha256Hex(List<int> b) async => [for (final x in (await Sha256().hash(b)).bytes) x.toRadixString(16).padLeft(2, '0')].join();

/// A relay that records the order of uploads and can refuse blob routes.
class SpyTransport extends MemoryTransport {
  final order = <String>[];
  TransportException? blobPutError;
  @override
  Future<void> put(String device, int seq, List<int> bytes) {
    order.add('put');
    return super.put(device, seq, bytes);
  }

  @override
  Future<void> putBlob(String hash, List<int> bytes) {
    order.add('putBlob');
    if (blobPutError != null) throw blobPutError!;
    return super.putBlob(hash, bytes);
  }
}

NormalizedBill nb(String ext) =>
    NormalizedBill(source: BillSource.pdf, externalId: ext, date: '2026-02-25', total: 1000, payee: 'Test Shop');

void main() {
  late VaultKey key;
  late SpyTransport relay;
  late WalletRepo repo;
  final extra = <WalletRepo>[];
  WalletRepo mk() {
    final r = WalletRepo.inMemory();
    extra.add(r);
    return r;
  }

  setUp(() {
    key = VaultKey.generate();
    relay = SpyTransport();
    repo = mk();
    // Changed (B1b): the relay creates a wallet only with a device's first file (RELAY_PROTOCOL.md: a blob PUT for an
    // unknown wallet is 404). A real bill file always comes with its bill row; a setting stands in for it here.
    repo.updateSettings({'returnReminderDays': 3});
  });
  tearDown(() {
    for (final r in extra) {
      r.close();
    }
    extra.clear();
  });

  Future<SyncReport> run(WalletRepo r, {SyncTransport? via}) => SyncEngine(via ?? relay, key).run(r);
  // Changed (P14): the upload queue is `blob_cache.uploaded = 0` now (`queuedBlobs`), no table of its own.
  List<String> table(WalletRepo r, String t) =>
      t == 'blob_outbox' ? r.queuedBlobs() : [for (final x in r.db.select('SELECT hash FROM $t')) x['hash'] as String];

  group('add', () {
    test('the ref: 64 lowercase hex hash, type, plain size', () async {
      final plain = bytesOf(3000);
      final ref = await BlobStore(repo, key).add(plain, 'jpg');
      expect(ref.hash, matches(RegExp(r'^[0-9a-f]{64}$')));
      expect((ref.type, ref.bytes), ('jpg', 3000));
    });

    test('hash = SHA-256 of the sealed bytes on the relay; the sealed bytes open with the key to the plain file', () async {
      final plain = bytesOf(5000);
      final ref = await BlobStore(repo, key).add(plain, 'pdf');
      await run(repo);
      final sealed = (await relay.getBlob(ref.hash))!;
      expect(await sha256Hex(sealed), ref.hash);
      expect(sealed, isNot(plain));
      expect(await unseal(sealed, key, aad: aadBlob), plain);
    });

    test('queued in blob_outbox until a run uploads it', () async {
      final ref = await BlobStore(repo, key).add(bytesOf(100), 'png');
      expect(table(repo, 'blob_outbox'), [ref.hash]);
      expect(await relay.getBlob(ref.hash), isNull);
      await run(repo);
      expect(table(repo, 'blob_outbox'), isEmpty);
    });

    test('size limit: 15 MiB is fine, one byte more is an ArgumentError (nothing queued)', () async {
      final store = BlobStore(repo, key);
      const max = 15 * 1024 * 1024;
      await expectLater(store.add(Uint8List(max + 1), 'pdf'), throwsArgumentError);
      expect(table(repo, 'blob_outbox'), isEmpty);
      expect(table(repo, 'blob_cache'), isEmpty);
      final ref = await store.add(bytesOf(max), 'pdf');
      expect(ref.bytes, max);
    }, timeout: const Timeout(Duration(minutes: 3)));

    test('the same file added twice is sealed again with a fresh nonce: two hashes', () async {
      final store = BlobStore(repo, key);
      final plain = bytesOf(500);
      final a = await store.add(plain, 'jpg'), b = await store.add(plain, 'jpg');
      // SPEC: RELAY_PROTOCOL says a new photo is sealed again with a fresh nonce, so equal plain bytes give different sealed bytes.
      expect(a.hash, isNot(b.hash));
      expect(await store.read(a.hash), plain);
      expect(await store.read(b.hash), plain);
    });
  });

  group('read', () {
    test('from the local cache without any transport, also when the relay is offline', () async {
      final store = BlobStore(repo, key);
      final plain = bytesOf(777);
      final ref = await store.add(plain, 'jpg');
      expect(await store.read(ref.hash), plain);
      relay.offline = true;
      expect(await store.read(ref.hash, transport: relay), plain);
    });

    test('a second device fetches, unseals and caches', () async {
      final plain = bytesOf(4000, 9);
      final ref = await BlobStore(repo, key).add(plain, 'png');
      await run(repo);
      final other = mk();
      final store = BlobStore(other, key);
      expect(await store.read(ref.hash), isNull, reason: 'not here, no transport');
      expect(await store.read(ref.hash, transport: relay), plain);
      expect(table(other, 'blob_cache'), [ref.hash]);
      expect(table(other, 'blob_outbox'), isEmpty, reason: 'a fetched file is never uploaded again');
      relay.offline = true;
      expect(await store.read(ref.hash), plain, reason: 'now cached');
    });

    test('not on the relay: null (also unreachable relay, malformed hash)', () async {
      final store = BlobStore(repo, key);
      expect(await store.read('a' * 64, transport: relay), isNull);
      expect(await store.read('not-a-hash', transport: relay), isNull);
      expect(await store.read('', transport: relay), isNull);
      relay.offline = true;
      expect(await store.read('b' * 64, transport: relay), isNull);
    });

    test('the wrong key: null, and nothing is cached', () async {
      final ref = await BlobStore(repo, key).add(bytesOf(300), 'jpg');
      await run(repo);
      final other = mk();
      final store = BlobStore(other, VaultKey.generate());
      expect(await store.read(ref.hash, transport: relay), isNull);
      expect(await store.read(ref.hash), isNull);
      expect(table(other, 'blob_cache'), isEmpty);
    });

    test('tampered bytes under their own hash: null, never other bytes', () async {
      final plain = bytesOf(1000);
      final ref = await BlobStore(repo, key).add(plain, 'jpg');
      await run(repo);
      final sealed = Uint8List.fromList((await relay.getBlob(ref.hash))!);
      sealed[sealed.length ~/ 2] ^= 0x55;
      final hash = await sha256Hex(sealed); // a relay serving different bytes under the matching new hash
      await relay.putBlob(hash, sealed);
      final other = mk();
      expect(await BlobStore(other, key).read(hash, transport: relay), isNull, reason: 'authentication fails');
      expect(table(other, 'blob_cache'), isEmpty);
    });

    test('bytes that do not match the requested hash: null', () async {
      final ref = await BlobStore(repo, key).add(bytesOf(1000), 'jpg');
      await run(repo);
      final good = (await relay.getBlob(ref.hash))!;
      // Another valid sealed file stored under the name of the first one cannot be put on a checking relay; a lying
      // transport is simulated by a relay that answers every hash with the same bytes.
      final liar = _Liar(good);
      final other = mk();
      expect(await BlobStore(other, key).read('c' * 64, transport: liar), isNull, reason: 'sha256(sealed) != hash');
      expect(table(other, 'blob_cache'), isEmpty);
    });
  });

  group('upload in SyncEngine.run', () {
    test('blobs go before the ops', () async {
      await BlobStore(repo, key).add(bytesOf(200), 'jpg');
      repo.importBill(nb('x'));
      final r = await run(repo);
      expect(relay.order.first, 'putBlob');
      expect(relay.order, contains('put'));
      expect(relay.order.indexOf('putBlob'), lessThan(relay.order.indexOf('put')));
      expect(r.blobsWaiting, 0);
    });

    test('a second run uploads nothing again', () async {
      await BlobStore(repo, key).add(bytesOf(200), 'jpg');
      await run(repo);
      relay.order.clear();
      await run(repo);
      expect(relay.order.where((o) => o == 'putBlob'), isEmpty);
    });

    test('a failed upload stays queued, the run still syncs the ops, blobsWaiting counts it', () async {
      final ref = await BlobStore(repo, key).add(bytesOf(200), 'jpg');
      final (id, _) = repo.importBill(nb('x'), file: ref);
      relay.blobPutError = const TransportException(TransportFailure.unreachable, 'down');
      final r = await run(repo);
      expect(r.sent, greaterThan(0));
      expect(r.blobsWaiting, 1);
      expect(table(repo, 'blob_outbox'), [ref.hash]);
      final other = mk();
      await run(other);
      expect(other.bills().single.id, id, reason: 'the bill row arrived without its file');
      relay.blobPutError = null;
      final r2 = await run(repo);
      expect(r2.blobsWaiting, 0);
      expect(table(repo, 'blob_outbox'), isEmpty);
      expect(await relay.getBlob(ref.hash), isNotNull);
    });

    test('an older relay (every blob route 404) keeps blobs queued and the run still syncs', () async {
      const notFound = TransportException(TransportFailure.missing, '404');
      relay.blobPutError = notFound;
      final ref = await BlobStore(repo, key).add(bytesOf(200), 'jpg');
      final (id, _) = repo.importBill(nb('x'), file: ref);
      final r = await run(repo);
      expect(r.sent, greaterThan(0));
      expect(r.blobsWaiting, 1);
      expect(table(repo, 'blob_outbox'), [ref.hash]);
      final other = mk();
      await run(other);
      expect(other.bills().single.id, id);
      expect(await BlobStore(other, key).read(ref.hash, transport: relay), isNull);
      // The relay is updated later: the next run uploads it.
      relay.blobPutError = null;
      final r2 = await run(repo);
      expect(r2.blobsWaiting, 0);
      expect(table(repo, 'blob_outbox'), isEmpty);
    });

    test('a refused blob (507, relay full) stays queued too', () async {
      final ref = await BlobStore(repo, key).add(bytesOf(200), 'jpg');
      relay.blobPutError = const TransportException(TransportFailure.other, 'full');
      final r = await run(repo);
      expect(r.blobsWaiting, 1);
      expect(table(repo, 'blob_outbox'), [ref.hash]);
    });

    test('two blobs, one failing: the other is stored', () async {
      final store = BlobStore(repo, key);
      final a = await store.add(bytesOf(100, 1), 'jpg'), b = await store.add(bytesOf(100, 2), 'jpg');
      final failing = _FailOne(relay, a.hash);
      final r = await run(repo, via: failing);
      expect(r.blobsWaiting, 1);
      expect(await relay.getBlob(b.hash), isNotNull);
      expect(await relay.getBlob(a.hash), isNull);
      expect(table(repo, 'blob_outbox'), [a.hash]);
    });
  });

  // Changed (P14, docs/context/P14_SPEC.md): clients never delete blobs on the relay; its GC collects files that no kept
  // snapshot declares. The B-stage "delete queues the blob" tests now pin that no DELETE is ever sent.
  group('deleteBill and the relay (P14: never deleted by clients)', () {
    Future<(String, BlobRef)> billWithFile(WalletRepo r, String ext, {BlobRef? ref}) async {
      final f = ref ?? await BlobStore(r, key).add(bytesOf(300, ext.hashCode & 0xff), 'jpg');
      final (id, _) = r.importBill(nb(ext), file: f);
      return (id, f);
    }

    test('deleting a bill keeps its file on the relay and in the cache; no DELETE is sent', () async {
      final (id, ref) = await billWithFile(repo, 'a');
      await run(repo);
      repo.deleteBill(id);
      await run(repo);
      expect(await relay.getBlob(ref.hash), isNotNull);
      expect(repo.cachedBlob(ref.hash, touch: false), isNotNull);
      expect(relay.order, isNot(contains('deleteBlob')));
      expect(relay.calls['deleteBlob'], isNull);
    });

    test('a blob shared by two bills stays after both are deleted', () async {
      final (a, ref) = await billWithFile(repo, 'a');
      final (b, _) = await billWithFile(repo, 'b', ref: ref);
      await run(repo);
      repo.deleteBill(a);
      repo.deleteBill(b);
      await run(repo);
      expect(await relay.getBlob(ref.hash), isNotNull);
      expect(repo.liveBlobHashes(), isEmpty);
    });

    test('deleting a bill whose file was never uploaded: it still goes up (the relay GC decides)', () async {
      final (id, ref) = await billWithFile(repo, 'a');
      repo.deleteBill(id);
      await run(repo);
      expect(await relay.getBlob(ref.hash), isNotNull);
      expect(table(repo, 'blob_outbox'), isEmpty);
    });

    test('a re-import and a restore send no DELETE either', () async {
      final (id, ref) = await billWithFile(repo, 'a');
      await run(repo);
      final other = await BlobStore(repo, key).add(bytesOf(300, 9), 'jpg');
      repo.importBill(nb('a'), file: other); // the bill keeps its file; the new one is forgotten locally
      repo.deleteBill(id);
      repo.importBill(nb('a')); // re-imported: revived
      await run(repo);
      final restored = mk();
      await restoreBackupBytes(restored, await backupBytes(repo, key), key);
      await run(restored);
      await run(repo);
      expect(relay.calls['deleteBlob'], isNull);
      expect(await relay.getBlob(ref.hash), isNotNull);
    });
  });

  group('cache', () {
    test('LRU: a queued (not yet uploaded) blob is never evicted, however full the cache gets', () async {
      // Changed (B1b): a 200 KiB limit and 14 KiB files instead of 200 MiB and 14 MiB (same shape, seconds not minutes).
      final store = BlobStore(repo, key, maxCacheBytes: 200 * 1024);
      final queued = await store.add(bytesOf(14 * 1024 * 1024 ~/ 1024, 100), 'pdf');
      final others = <BlobRef>[];
      for (var i = 0; i < 15; i++) {
        others.add(await store.add(bytesOf(14 * 1024, i), 'pdf'));
        // Upload all but the first blob: hide it from the run by queueing only the new ones via a transport that refuses it.
        await run(repo, via: _FailOne(relay, queued.hash));
      }
      expect(table(repo, 'blob_outbox'), [queued.hash]);
      expect(table(repo, 'blob_cache'), contains(queued.hash));
      expect(await store.read(queued.hash), isNotNull, reason: 'still readable without the relay');
      final cached = table(repo, 'blob_cache');
      expect(cached.length, lessThan(16), reason: 'the cache evicted something to stay under its limit');
      // Anything evicted is still on the relay.
      for (final r in others) {
        if (!cached.contains(r.hash)) {
          expect(await store.read(r.hash), isNull);
          expect(await store.read(r.hash, transport: relay), isNotNull);
        }
      }
      // And the queued blob still goes out on the next run.
      await run(repo);
      expect(await relay.getBlob(queued.hash), isNotNull);
    });
  });
}

/// Answers every blob read with the same bytes (a lying relay).
class _Liar extends MemoryTransport {
  final List<int> bytes;
  _Liar(this.bytes);
  @override
  Future<List<int>?> getBlob(String hash) async => bytes;
}

/// Refuses the upload of one blob, forwards the rest to [base].
class _FailOne extends MemoryTransport {
  final MemoryTransport base;
  final String hash;
  _FailOne(this.base, this.hash);
  @override
  Future<RelayState> state() => base.state();
  @override
  Future<void> put(String device, int seq, List<int> bytes) => base.put(device, seq, bytes);
  @override
  Future<List<int>> get(String device, int seq) => base.get(device, seq);
  @override
  Future<void> ack(String device, Map<String, int> cursors) => base.ack(device, cursors);
  @override
  Future<void> putSnapshot(String id, Map<String, int> covers, List<int> bytes) => base.putSnapshot(id, covers, bytes);
  @override
  Future<List<int>> getSnapshot(String id) => base.getSnapshot(id);
  @override
  Future<void> putBlob(String h, List<int> bytes) {
    if (h == hash) throw const TransportException(TransportFailure.unreachable, 'refused');
    return base.putBlob(h, bytes);
  }

  @override
  Future<List<int>?> getBlob(String h) => base.getBlob(h);
  @override
  Future<void> putSnapshotBlobs(String id, List<String> hashes) => base.putSnapshotBlobs(id, hashes);
}
